{
  "version": "0.2",
  "phases": {
    "install": {
      "runtime-versions": {
        "nodejs": "20"
      },
      "commands": [
        "npm install -g pnpm"
      ]
    },
    "pre_build": {
      "commands": [
        "pnpm install --frozen-lockfile"
      ]
    },
    "build": {
      "commands": [
        "pnpm --filter api build || true",
        "cd infrastructure && npx cdk synth -o ../cdk.out"
      ]
    }
  },
  "artifacts": {
    "base-directory": "cdk.out",
    "files": [
      "**/*"
    ]
  }
}

{
  "version": "0.2",
  "phases": {
    "build": {
      "commands": [
        "INSTANCE_ID=$(aws ssm get-parameter --name /indiai/ec2-instance-id --region us-east-1 --query Parameter.Value --output text)",
        "COMMAND_ID=$(aws ssm send-command --region ap-south-1 --instance-ids $INSTANCE_ID --document-name AWS-RunShellScript --parameters commands=[\"export HOME=/root\",\"git config --global --add safe.directory /app/indiAi\",\"git -C /app/indiAi pull origin main\",\"chown -R ec2-user:ec2-user /app/indiAi\",\"cd /app/indiAi && docker compose down\",\"cd /app/indiAi && docker compose build --no-cache\",\"cd /app/indiAi && docker compose up -d\",\"sleep 15\",\"curl -f http://localhost:3000/api/v1/health && echo Health-check-passed || echo Health-check-failed\"] --query Command.CommandId --output text)",
        "aws ssm wait command-executed --command-id $COMMAND_ID --instance-id $INSTANCE_ID --region ap-south-1",
        "aws ssm get-command-invocation --command-id $COMMAND_ID --instance-id $INSTANCE_ID --region ap-south-1"
      ]
    }
  }
}

